package explorer

import (
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// The clone list is the item level of a clone run (D3).
//
// It used to keep its own five states, its own rows, its own index and its own
// spinner frame — a fifth bookkeeping beside the four internal/jobs replaced,
// and the one the plan named as the prototype to generalise. Those five states
// are where jobs.ItemState came from, so the mapping is direct:
//
//	queued        → ItemQueued
//	cloning       → ItemRunning
//	cloned        → ItemDone
//	already there → ItemSkipped
//	failed        → ItemFailed
//
// What this screen is now is a **rendering** of the run: the rows are the
// snapshot's items, in the order the walk found them, and the frame is the
// router's (D5). Nothing here is authoritative, which is what lets `:jobs` show
// the same run without either copy drifting from the other.

// cloneRow is one target of the run, with the shared frame stamped on.
//
// The frame rides on the row because the columns are built once and close over
// nothing — the same reason jobsview has runRow. It is text rather than a
// rendered spinner because a table cell must carry no escape sequence
// (Rule 122).
type cloneRow struct {
	item  jobs.Item
	frame string
}

// cloneList is the ModeCloning screen: the run in flight and the table showing
// it. It is the progress view and the report both — decision 9 leaves modals
// for yes/no confirmations only.
type cloneList struct {
	table datatable.Model[cloneRow]

	// run is the last snapshot of this screen's run. It is a copy, replaced
	// whole on every broadcast — there is nothing to reconcile, which is what
	// removed the index and the upsert.
	run    jobs.Run
	target string

	// events is the pipeline's channel, and the only thing this struct still
	// owns. It is not state: it is what waitForCloneEvent blocks on.
	events <-chan cloneEvent

	// cancelling is set by `esc` and cleared by nothing: a run that is stopping
	// cannot be restarted, only awaited. A second `esc` must not force, because
	// forcing is the half-cloned directory decision 12 avoids.
	//
	// It is kept here rather than read back from the run for one frame's worth
	// of honesty: `esc` asks the router, and the answer arrives in the next
	// broadcast. Without it the key would look ignored until then.
	cancelling bool
}

const (
	colCloneStatusMin = 16
	colClonePathMin   = 30
	colCloneDetailMin = 20
)

// The column order, named so a test asserting on a cell does not hard-code the
// position it happens to sit at today.
const (
	colCloneRepository = iota
	colCloneDetail
	colCloneStatus
)

func newCloneList(target string, events <-chan cloneEvent) *cloneList {
	return &cloneList{
		target: target,
		events: events,
		table: datatable.New(datatable.Config[cloneRow]{
			Columns: cloneColumns(),
			// Discovery order, deliberately: it is the order things happened, and
			// a list that reorders itself while it fills is unreadable. `.` still
			// sorts on demand.
			SortColumn: -1,
		}),
	}
}

// cloneColumns describes the clone list.
//
// The repository comes first and the status last. The rows are one long list of
// paths under a common prefix, so the name is what the eye runs down to find a
// line; a status column on the left pushes every one of them right by sixteen
// cells and puts the changing text where the stable text should be.
func cloneColumns() []datatable.Column[cloneRow] {
	return []datatable.Column[cloneRow]{
		{
			Title: "Repository", Sizing: datatable.SizingContent, MinWidth: colClonePathMin, Flex: 2, TruncateHead: true,
			Cell:   func(r cloneRow) string { return r.item.Name() },
			Less:   func(a, b cloneRow) bool { return strings.ToLower(a.item.Name()) < strings.ToLower(b.item.Name()) },
			Search: func(r cloneRow) string { return r.item.Name() },
		},
		{
			Title: "Detail", Sizing: datatable.SizingContent, Optional: true, MinWidth: colCloneDetailMin, Flex: 1,
			Cell:   func(r cloneRow) string { return r.item.Detail },
			Search: func(r cloneRow) string { return r.item.Detail },
		},
		{
			Title: "Status", Sizing: datatable.SizingFixed, MinWidth: colCloneStatusMin,
			Cell:  cloneStatusLabel,
			Style: cloneStatusStyle,
			Less:  func(a, b cloneRow) bool { return a.item.State < b.item.State },
		},
	}
}

// cloneStatusLabel is the status cell: an icon and a word, plain text.
//
// The words are the clone's, not the registry's: "already there" is what a skip
// means here, where a sync's skip means something else entirely. The state is
// shared, the wording is the view's — the same split Reporter draws.
func cloneStatusLabel(r cloneRow) string {
	switch r.item.State {
	case jobs.ItemRunning:
		return r.frame + " cloning"
	case jobs.ItemDone:
		return theme.IconOK + " cloned"
	case jobs.ItemSkipped:
		return theme.IconSkipped + " already there"
	case jobs.ItemFailed:
		return theme.IconError + " failed"
	default:
		return theme.IconPending + " queued"
	}
}

// cloneStatusStyle colours the status cell.
//
// The five states are the whole vocabulary of this screen, and they are the one
// thing a run of forty rows is read for: which ones failed, which are still
// going, which were already on disk and were left alone.
func cloneStatusStyle(r cloneRow) lipgloss.Style {
	switch r.item.State {
	case jobs.ItemDone:
		return theme.StatusOKStyle
	case jobs.ItemFailed:
		return theme.StatusErrorStyle
	case jobs.ItemRunning:
		return lipgloss.NewStyle().Foreground(theme.ColorHighlight)
	default: // queued, and already there — neither is news
		return theme.DimStyle
	}
}

// setRun replaces the screen's copy of the run and rebuilds the table.
//
// The frame is stamped on the running rows here rather than held on each item,
// because it belongs to the list and not to any repository: one spinner, on
// every row that is going.
func (l *cloneList) setRun(run jobs.Run, frame string) {
	l.run = run
	items := make([]cloneRow, len(run.Items))
	for i, item := range run.Items {
		row := cloneRow{item: item}
		if item.State == jobs.ItemRunning {
			row.frame = frame
		}
		items[i] = row
	}
	l.table.SetItems(items)
}

// finished reports whether the run has settled: the walk sealed, and every
// target done with.
func (l *cloneList) finished() bool { return l.run.Finished() }

// running counts the clones still in flight, which is what `esc` has to wait
// for and what the view states while it does.
func (l *cloneList) running() int {
	n := 0
	for _, item := range l.run.Items {
		if item.State == jobs.ItemRunning {
			n++
		}
	}
	return n
}

// counts is the header line: what has been found and how it went.
func (l *cloneList) counts() (found, cloned, present, failed int) {
	c := l.run.Counts()
	return l.run.Total(), c[jobs.ItemDone], c[jobs.ItemSkipped], c[jobs.ItemFailed]
}

// failures returns the failed paths, for the log and the footer. Decision 13
// discards the list on `esc`, and workspaces records only the successes — a
// failure that wrote nothing leaves nothing behind, so it has to be said while
// the view is still alive.
func (l *cloneList) failures() []string {
	var out []string
	for _, item := range l.run.Items {
		if item.State == jobs.ItemFailed {
			out = append(out, item.Target)
		}
	}
	return out
}

// cloneRunFrom picks this screen's run out of the snapshot.
//
// The newest clone run, because there is exactly one at a time: ModeCloning
// owns the display while it goes, so a second could only start after this one
// has been closed. It is the invariant Registry.openRun rests on, read from the
// other side.
//
// A settled run still matches, which is what the report needs: the screen stays
// up after the walk has sealed, and `esc` is what finally drops it.
func cloneRunFrom(runs []jobs.Run) (jobs.Run, bool) {
	for i := len(runs) - 1; i >= 0; i-- {
		if runs[i].Kind == jobs.KindClone {
			return runs[i], true
		}
	}
	return jobs.Run{}, false
}
package explorer

import (
	"reflect"
	"strings"
	"testing"

	"github.com/charmbracelet/bubbles/spinner"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/testutil"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// DEVDESK-147 / DEVDESK-223 step 3: column 0 of the explorer tree is the
// activity column. The row carries a state, the blink phase is read at render.

func treeLine(t *testing.T, m Model, name string) string {
	t.Helper()
	for _, l := range strings.Split(m.table.View(), "\n") {
		if strings.Contains(l, name) {
			return l
		}
	}
	t.Fatalf("no rendered line holds %q:\n%s", name, m.table.View())
	return ""
}

func anyGlyph(line string) bool {
	if strings.Contains(line, indicator.Glyph(indicator.Running, false)) {
		return true
	}
	for _, s := range indicator.States() {
		if g := indicator.Glyph(s, true); g != "" && strings.Contains(line, g) {
			return true
		}
	}
	return false
}

// deleting returns a loaded model whose "alpha" row has a delete in flight.
func deleting(t *testing.T) Model {
	t.Helper()
	return feed(t, loadedModel(t), jobs.ChangedMsg{
		Runs: actRunning(t, jobs.KindDelete, actCtx, "alpha"), Context: actCtx,
	})
}

func TestColumnZeroIsTheActivityColumn(t *testing.T) {
	c := explorerColumns()[0]
	if c.Title != "" || c.Sizing != datatable.SizingFixed || c.MinWidth != datatable.IconColumnWidth {
		t.Errorf("column 0 = %q/%v/%d, want untitled SizingFixed IconColumnWidth", c.Title, c.Sizing, c.MinWidth)
	}
	if c.Indicator == nil {
		t.Error("column 0 is not built by datatable.IndicatorColumn")
	}
	if c.Less != nil || c.Search != nil {
		t.Errorf("column 0 declares Less=%v Search=%v, want neither", c.Less != nil, c.Search != nil)
	}
	m := loadedModel(t)
	shapes := m.table.Shapes()
	if len(shapes) == 0 || !shapes[0].Indicator {
		t.Errorf("the live tree has no activity column 0: %+v", shapes)
	}
}

func TestTheViewExposesItsTreeToTheActivityGuard(t *testing.T) {
	av, ok := any(loadedModel(t)).(interface {
		ActivityTables() map[string]datatable.ActivityTable
	})
	if !ok {
		t.Fatal("Model does not expose ActivityTables()")
	}
	tables := av.ActivityTables()
	tbl, ok := tables["explorer/tree"]
	if !ok || len(tables) != 1 {
		t.Fatalf("ActivityTables() keys = %v, want exactly [explorer/tree] (the clone list is A-10b)", tables)
	}
	if shapes := tbl.Shapes(); len(shapes) == 0 || !shapes[0].Indicator {
		t.Errorf("the reported table has no activity column 0: %+v", shapes)
	}
}

func TestTheRowCarriesNoFrameAnyMore(t *testing.T) {
	if _, has := reflect.TypeOf(explorerRow{}).FieldByName("frame"); has {
		t.Error("explorerRow still has a frame field: the blink phase is read at render")
	}
}

func TestRowsAreStampedFromTheRegistrySnapshot(t *testing.T) {
	m := deleting(t)
	row, ok := rowFor(m, "alpha")
	if !ok {
		t.Fatal("no alpha row")
	}
	if row.Activity != indicator.Running {
		t.Errorf("alpha Activity = %v, want Running", row.Activity)
	}
	if other, _ := rowFor(m, "beta"); other.Activity != indicator.Idle {
		t.Errorf("beta Activity = %v, want Idle", other.Activity)
	}
	// Done: back to the icon.
	m = feed(t, m, jobs.ChangedMsg{Context: actCtx})
	if row, _ := rowFor(m, "alpha"); row.Activity != indicator.Idle {
		t.Errorf("a settled row: Activity = %v, want Idle", row.Activity)
	}
}

func TestEachActivityStateRendersItsGlyphOnItsRow(t *testing.T) {
	run := actRunning(t, jobs.KindDelete, actCtx, "alpha")
	fail := actFailure(jobs.KindDelete, actCtx, "alpha", "check logs")
	tests := []struct {
		name  string
		runs  []jobs.Run
		fails []jobs.Failure
		blink bool
		state indicator.State
	}{
		{"running, phase on", run, nil, true, indicator.Running},
		{"running, phase off", run, nil, false, indicator.Running},
		{"failed, phase on", nil, []jobs.Failure{fail}, true, indicator.Failed},
		{"failed, phase off", nil, []jobs.Failure{fail}, false, indicator.Failed},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			m := feed(t, loadedModel(t),
				jobs.ChangedMsg{Runs: tc.runs, Failures: tc.fails, Context: actCtx},
				jobs.FrameMsg{Blink: tc.blink})
			line := treeLine(t, m, "alpha")
			if want := indicator.Glyph(tc.state, tc.blink); !strings.Contains(line, want) {
				t.Errorf("row lacks %q:\n%s", want, line)
			}
			if strings.Contains(line, theme.IconNamespace) {
				t.Errorf("the glyph shares the row with the resting icon:\n%s", line)
			}
			if other := treeLine(t, m, "beta"); anyGlyph(other) {
				t.Errorf("an untouched row shows an activity glyph:\n%s", other)
			}
		})
	}
}

func TestAFailedCreateOnARealRowNeverPaintsIt(t *testing.T) {
	// H1 / Q1-C: create is read on placeholders only.
	m := feed(t, loadedModel(t), jobs.ChangedMsg{
		Failures: []jobs.Failure{actFailure(jobs.KindCreate, actCtx, "alpha", "boom")}, Context: actCtx,
	})
	if line := treeLine(t, m, "alpha"); anyGlyph(line) {
		t.Errorf("a create failure marks a healthy row:\n%s", line)
	}
}

func TestAnIdleRowKeepsItsKindIcon(t *testing.T) {
	m := feed(t, drilledModel(t), jobs.FrameMsg{Blink: true})
	if line := treeLine(t, m, "sub"); !strings.Contains(line, theme.IconNamespace) {
		t.Errorf("idle group lacks %q:\n%s", theme.IconNamespace, line)
	}
	if line := treeLine(t, m, "api"); !strings.Contains(line, theme.IconRepository) {
		t.Errorf("idle repository lacks %q:\n%s", theme.IconRepository, line)
	}
}

func TestAPlaceholderBlinksWhileItsCreateRuns(t *testing.T) {
	m := loadedModel(t)
	m, _ = step(t, m, components.CreationFormSubmitMsg{FormType: components.FormTypeGroup, Name: "new"})
	m = feed(t, m,
		jobs.ChangedMsg{Runs: actRunning(t, jobs.KindCreate, actCtx, "new"), Context: actCtx},
		jobs.FrameMsg{Blink: true})
	row, ok := rowFor(m, "new")
	if !ok || row.Activity != indicator.Running {
		t.Fatalf("placeholder = %+v (found %v), want Running", row.Activity, ok)
	}
	if line := treeLine(t, m, "new"); !strings.Contains(line, indicator.Glyph(indicator.Running, true)) {
		t.Errorf("placeholder lacks the running dot:\n%s", line)
	}
}

// A frame moves the glyph and rebuilds nothing (H5): the rows are the same
// values before and after.
func TestAFrameBlinksWithoutRebuildingTheRows(t *testing.T) {
	m := feed(t, deleting(t), jobs.FrameMsg{Blink: true})
	on := treeLine(t, m, "alpha")
	before := append([]explorerRow(nil), m.table.Items()...)

	m = feed(t, m, jobs.FrameMsg{Blink: false})
	off := treeLine(t, m, "alpha")

	if on == off {
		t.Fatalf("the glyph did not change with the phase:\n%s", on)
	}
	if !strings.Contains(on, indicator.Glyph(indicator.Running, true)) ||
		!strings.Contains(off, indicator.Glyph(indicator.Running, false)) {
		t.Errorf("phase glyphs wrong:\non : %s\noff: %s", on, off)
	}
	if m.table.BlinkPhase() {
		t.Error("the table did not take the blink phase")
	}
	if !reflect.DeepEqual(before, m.table.Items()) {
		t.Error("a frame rebuilt the tree rows")
	}
}

// SetItems resets nothing observable, so detect a rebuild by identity: a frame
// must not reallocate the backing slice.
func TestAFrameDoesNotCallSetItems(t *testing.T) {
	m := deleting(t)
	before := m.table.Items()
	m = feed(t, m, jobs.FrameMsg{Blink: true}, jobs.FrameMsg{Blink: false})
	after := m.table.Items()
	if len(before) == 0 || &before[0] != &after[0] {
		t.Error("the tree rows were rebuilt by a frame")
	}
}

func TestACloneListKeepsItsFrameWhileTheTreeTakesThePhase(t *testing.T) {
	h := cloning(t)
	h.emit(found("alpha/api"), began("alpha/api"))
	h.m = feed(t, h.m, jobs.FrameMsg{Frame: "X", Blink: true})
	rows := h.m.clone.table.Table().Rows()
	if len(rows) != 1 || !strings.HasPrefix(rows[0][colCloneStatus], "X cloning") {
		t.Fatalf("clone status = %v, want the frame X (A-10b keeps jobFrame)", rows)
	}
	if !h.m.table.BlinkPhase() {
		t.Error("the tree table did not take the phase while the clone list was open")
	}
}

// ChangedMsg during a clone returns early; the tree rows must catch up when
// the list closes.
func TestTheRowsAreRebuiltWhenTheCloneListCloses(t *testing.T) {
	h := cloning(t)
	h.m = feed(t, h.m, jobs.ChangedMsg{
		Runs: actRunning(t, jobs.KindDelete, actCtx, "alpha/api"), Context: actCtx,
	})
	next, _ := h.m.handleCloneClose()
	m := next.(Model)
	row, ok := rowFor(m, "alpha/api")
	if !ok || row.Activity != indicator.Running {
		t.Errorf("after the close, alpha/api = %v (found %v), want Running", row.Activity, ok)
	}
}

func TestInSelectionTheRestIsTheCheckboxAndFailedShowsItToo(t *testing.T) {
	m := feed(t, drilledModel(t), jobs.ChangedMsg{
		Runs:     actRunning(t, jobs.KindDelete, actCtx, "alpha/sub"),
		Failures: []jobs.Failure{actFailure(jobs.KindDelete, actCtx, "alpha/api", "x")},
		Context:  actCtx,
	}, testutil.Key(keymap.Clone))
	if m.mode != ModeSelecting {
		t.Fatalf("mode = %v, want ModeSelecting", m.mode)
	}
	sub, _ := rowFor(m, "alpha/sub")
	api, _ := rowFor(m, "alpha/api")
	if sub.Activity != indicator.Running {
		t.Errorf("running row in selection: Activity = %v, want Running (keeps its glyph)", sub.Activity)
	}
	if api.Activity != indicator.Idle {
		t.Errorf("failed row in selection: Activity = %v, want Idle so the checkbox shows (H2)", api.Activity)
	}
	if got := restIcon(api); got != theme.IconCheckbox {
		t.Errorf("failed row rest = %q, want the checkbox", got)
	}
	if line := treeLine(t, m, "api"); !strings.Contains(line, theme.IconCheckbox) || anyGlyph(line) {
		t.Errorf("failed row in selection should show its checkbox only:\n%s", line)
	}
}

func TestNoTreeCellCarriesASpinnerRuneOrEscape(t *testing.T) {
	m := feed(t, deleting(t), jobs.FrameMsg{Frame: spinner.Dot.Frames[0], Blink: true})
	for _, row := range m.table.Items() {
		for i, col := range explorerColumns() {
			cell := col.Cell(row)
			if strings.Contains(cell, "\x1b") {
				t.Errorf("%s col %d carries an escape: %q", row.node.FullPath, i, cell)
			}
			for _, f := range spinner.Dot.Frames {
				if strings.Contains(cell, f) {
					t.Errorf("%s col %d holds a spinner rune: %q", row.node.FullPath, i, cell)
				}
			}
		}
	}
}

func TestRule116At60Columns(t *testing.T) {
	m := feed(t, deleting(t), testutil.Resize(60, 30))
	if got := m.table.RenderedWidth(); got != 58 {
		t.Errorf("RenderedWidth = %d at 60 columns, want 58", got)
	}
}
